// swift-tools-version:6.0
// vphone-linux: build vphone-cli's firmware tooling on Linux. Sources/ is generated by
// sync-sources.sh from a vphone-cli checkout; Shims/ provides Linux stand-ins for Apple modules.
import PackageDescription

// vphone-cli's files are written for macOS, where Darwin (libc) and URLSession come with
// Foundation. Import the Linux stand-ins into every file; sync-sources.sh rewrites their
// explicit `import Darwin` etc. to the VL* stand-ins (named apart so that dependencies'
// `canImport(Darwin)` checks stay false on Linux).
let swift6: [SwiftSetting] = [
    .swiftLanguageMode(.v5),
    .unsafeFlags(["-Xfrontend", "-import-module", "-Xfrontend", "VLDarwin",
                  "-Xfrontend", "-import-module", "-Xfrontend", "FoundationNetworking"]),
]

let package = Package(
    name: "vphone-linux-create",
    platforms: [.macOS(.v14)],
    dependencies: [
        // The versions vphone-cli 2.9.4 pins (its Package.resolved files).
        .package(url: "https://github.com/apple/swift-crypto.git", exact: "3.15.1"),
        .package(url: "https://github.com/apple/swift-argument-parser.git", exact: "1.3.1"),
        .package(url: "https://github.com/p-x9/MachOKit.git", exact: "0.55.0"),
        .package(url: "https://github.com/Lakr233/libcapstone-spm.git", exact: "0.1.3"),
    ],
    targets: [
        // Linux stand-ins for Apple modules (VL = vphone-linux).
        .target(name: "VLCryptoKit", dependencies: [.product(name: "Crypto", package: "swift-crypto")], path: "Shims/VLCryptoKit"),
        // Minimal stand-ins for Apple's AppleArchive (OTA payloads) and swift-system (`System`).
        .target(name: "AppleArchive", dependencies: ["System"], path: "Shims/AppleArchive"),
        .target(name: "System", path: "Shims/System"),
        .target(name: "LinuxSys", path: "Shims/LinuxSys"),
        .target(name: "VLDarwin", dependencies: ["LinuxSys"], path: "Shims/VLDarwin"),
        .target(name: "VLCompression", path: "Shims/VLCompression",
                linkerSettings: [.linkedLibrary("lzfse"), .linkedLibrary("z"), .linkedLibrary("lzma")]),
        .target(name: "VLCoreGraphics", path: "Shims/VLCoreGraphics"),
        .target(name: "VLMachO", dependencies: [.product(name: "MachOKitC", package: "MachOKit")], path: "Shims/VLMachO"),
        .target(name: "VLCoreServices", path: "Shims/VLCoreServices"),
        .target(name: "VLos", path: "Shims/VLos"),
        .target(name: "VLUniformTypeIdentifiers", path: "Shims/VLUniformTypeIdentifiers"),
        .systemLibrary(name: "VLzlib", path: "Shims/VLzlib"),
        .systemLibrary(name: "libarchive", path: "Shims/libarchive"),
        // Headers vendored from upstream for the installed libarchive version; links the system library.
        .target(name: "ArchiveKit", dependencies: ["libarchive"], path: "Shims/ArchiveKit",
                linkerSettings: [.unsafeFlags(["-L", "Shims/libarchive/lib"])]),
        .target(name: "Img4OpenSSL", path: "Shims/Img4OpenSSL", linkerSettings: [.linkedLibrary("crypto")]),
        .target(name: "Img4tool", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "VLCompression", "Img4OpenSSL"], path: "Vendor/Img4tool", exclude: ["LICENSE", "README.md"]),

        // vphone-cli's modules (Sources/ from sync-sources.sh).
        .target(name: "VPhonePatchKit", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", .product(name: "Capstone", package: "libcapstone-spm")], path: "Sources/VPhonePatchKit", swiftSettings: swift6),
        .target(name: "VPhoneCoreKit", dependencies: ["VLCryptoKit", .product(name: "_CryptoExtras", package: "swift-crypto"), "VLDarwin", "LinuxSys", "VLCompression", "VLCoreGraphics", "VLCoreServices", "VLUniformTypeIdentifiers", .product(name: "ArgumentParser", package: "swift-argument-parser")], path: "Sources/VPhoneCoreKit", swiftSettings: swift6),
        .target(name: "VPhoneSign", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "VLMachO"], path: "Sources/VPhoneSign", swiftSettings: swift6),
        .target(name: "VPhoneArchiveKit", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "ArchiveKit", "VPhoneCoreKit", "AppleArchive"], path: "Sources/VPhoneArchiveKit", swiftSettings: swift6),
        .executableTarget(name: "vphone-cli", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "Img4tool", "VPhonePatchKit", "VPhoneCoreKit", "VPhoneSign", "VPhoneArchiveKit", "FirmwarePatcher", "VPhoneRestore", "MobileRestoreCore", "MobileRecoveryCore", "VLzlib", .product(name: "ArgumentParser", package: "swift-argument-parser"), .product(name: "MachOKit", package: "MachOKit")], path: "Sources/VPhoneCommand", swiftSettings: swift6),
        // vphone-cli's restore engine: libirecovery and idevicerestore (upstream C, vphone-cli's
        // configuration) over the system libimobiledevice, libplist, libtatsu and libusb.
        .target(name: "MobileRecoveryCore", path: "Sources/MobileRecoveryCore", publicHeadersPath: "Include",
                cSettings: [.headerSearchPath("."), .define("HAVE_CONFIG_H", to: "1"), .define("IRECV_STATIC", to: "1"),
                            .unsafeFlags(["-I/usr/include/libusb-1.0"])],
                linkerSettings: [.linkedLibrary("usb-1.0"), .linkedLibrary("imobiledevice-glue-1.0"), .linkedLibrary("plist-2.0")]),
        .target(name: "MobileRestoreCore", dependencies: ["MobileRecoveryCore"], path: "Sources/MobileRestoreCore", publicHeadersPath: "Include",
                cSettings: [.headerSearchPath("."), .headerSearchPath("Bridge"), .headerSearchPath("Core"), .headerSearchPath("Recovery"), .headerSearchPath("Transfer"),
                            .headerSearchPath("Firmware"), .headerSearchPath("Firmware/Containers"), .headerSearchPath("Firmware/Images"),
                            .headerSearchPath("../MobileRecoveryCore/Include"),
                            // <compression.h> and <CommonCrypto/CommonDigest.h> for openavb.c (2.12+).
                            .headerSearchPath("../../Shims/VLCompression/include"),
                            .headerSearchPath("../../Shims/CommonCrypto/include"),
                            .define("HAVE_CONFIG_H", to: "1"), .define("IDEVICERESTORE_NOMAIN", to: "1"), .define("IRECV_STATIC", to: "1")],
                linkerSettings: [.linkedLibrary("imobiledevice-1.0"), .linkedLibrary("imobiledevice-glue-1.0"), .linkedLibrary("plist-2.0"),
                                 .linkedLibrary("usbmuxd-2.0"), .linkedLibrary("tatsu"), .linkedLibrary("curl"), .linkedLibrary("z"),
                                 .linkedLibrary("crypto")]),
        .target(name: "VPhoneRestore", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "VLzlib", "MobileRestoreCore", "MobileRecoveryCore", "VPhoneCoreKit"],
                path: "Sources/VPhoneRestore", swiftSettings: swift6),
        .target(name: "FirmwarePatcher", dependencies: ["VLCryptoKit", "VLDarwin", "LinuxSys", "Img4tool", "VPhonePatchKit", "VPhoneCoreKit", "VPhoneSign", "VPhoneArchiveKit", "VLos", .product(name: "MachOKit", package: "MachOKit")], path: "Sources/FirmwarePatcher", swiftSettings: swift6),
    ]
)
